-- O servidor cria estas tabelas automaticamente no primeiro arranque.
-- Este ficheiro é uma referência para inspeção/manual setup.
CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(70) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user',plan TEXT NOT NULL DEFAULT 'free',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS predictions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,sport TEXT NOT NULL,event_name VARCHAR(180) NOT NULL,prediction VARCHAR(120) NOT NULL,probabilities_json TEXT,event_date TEXT,actual_result VARCHAR(120),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS paper_wallets(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,balance NUMERIC(14,2) NOT NULL DEFAULT 1000,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS paper_trades(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,prediction_id BIGINT REFERENCES predictions(id) ON DELETE SET NULL,event_name VARCHAR(180) NOT NULL,selection VARCHAR(100) NOT NULL,odds NUMERIC(12,2) NOT NULL,stake NUMERIC(14,2) NOT NULL,sport VARCHAR(40) NOT NULL DEFAULT 'Outro',status TEXT NOT NULL DEFAULT 'open',profit NUMERIC(14,2) NOT NULL DEFAULT 0,cashout_value NUMERIC(14,2),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),settled_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS paper_resets(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,old_balance NUMERIC(14,2) NOT NULL,new_balance NUMERIC(14,2) NOT NULL DEFAULT 1000,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
